document.addEventListener('DOMContentLoaded',()=>{const themeToggle=document.getElementById('theme-toggle');if(themeToggle){themeToggle.addEventListener('click',()=>{const currentTheme=document.documentElement.getAttribute('data-theme');const newTheme=currentTheme==='dark' ? 'light':'dark';document.documentElement.setAttribute('data-theme',newTheme);localStorage.setItem('theme',newTheme);});}const hamburger=document.getElementById('hamburger');const navMenu=document.getElementById('nav-menu');const navLinks=document.querySelectorAll('.nav-link');if(hamburger && navMenu){hamburger.addEventListener('click',()=>{const isActive=hamburger.classList.toggle('active');navMenu.classList.toggle('active');hamburger.setAttribute('aria-expanded',isActive);if(isActive){document.body.style.overflow='hidden';}else{document.body.style.overflow='';}});navLinks.forEach(link=>{link.addEventListener('click',()=>{hamburger.classList.remove('active');navMenu.classList.remove('active');hamburger.setAttribute('aria-expanded','false');document.body.style.overflow='';});});}const contactForm=document.getElementById('contact-form');const nameInput=document.getElementById('contact-name');const emailInput=document.getElementById('contact-email');const messageInput=document.getElementById('contact-message');const nameError=document.getElementById('name-error');const emailError=document.getElementById('email-error');const messageError=document.getElementById('message-error');const formStatus=document.getElementById('form-status');const emailRegex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;function validateName(){if(!nameInput.value.trim()){nameInput.classList.add('invalid');nameInput.setAttribute('aria-invalid','true');nameError.textContent='Name is required.';return false;}else{nameInput.classList.remove('invalid');nameInput.setAttribute('aria-invalid','false');nameError.textContent='';return true;}}function validateEmail(){const val=emailInput.value.trim();if(!val){emailInput.classList.add('invalid');emailInput.setAttribute('aria-invalid','true');emailError.textContent='Email is required.';return false;}else if(!emailRegex.test(val)){emailInput.classList.add('invalid');emailInput.setAttribute('aria-invalid','true');emailError.textContent='Please enter a valid email address.';return false;}else{emailInput.classList.remove('invalid');emailInput.setAttribute('aria-invalid','false');emailError.textContent='';return true;}}function validateMessage(){if(!messageInput.value.trim()){messageInput.classList.add('invalid');messageInput.setAttribute('aria-invalid','true');messageError.textContent='Message is required.';return false;}else{messageInput.classList.remove('invalid');messageInput.setAttribute('aria-invalid','false');messageError.textContent='';return true;}}if(nameInput)nameInput.addEventListener('blur',validateName);if(emailInput)emailInput.addEventListener('blur',validateEmail);if(messageInput)messageInput.addEventListener('blur',validateMessage);if(contactForm){contactForm.addEventListener('submit',(e)=>{e.preventDefault();const isNameValid=validateName();const isEmailValid=validateEmail();const isMessageValid=validateMessage();if(isNameValid && isEmailValid && isMessageValid){formStatus.className='form-status-alert success';formStatus.innerHTML=`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path><polyline points="22 4 12 14.01 9 11.01"></polyline></svg>Message sent successfully! We will get back to you shortly. `;contactForm.reset();setTimeout(()=>{formStatus.className='form-status-alert';formStatus.innerHTML='';},5000);}else{formStatus.className='form-status-alert error';formStatus.innerHTML=`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg>Please fix the errors in the form before submitting. `;}});}const blogGrid=document.getElementById('blog-grid');const categories=['Productivity','Engineering','Workflow','SaaS','Security','Management'];const dates=[ 'June 18,2026','June 15,2026','June 10,2026','June 08,2026','June 02,2026','May 28,2026' ];function renderSkeletons(){if(!blogGrid)return;const skeletonTemplate=`<div class="skeleton-card" aria-hidden="true"><div class="skeleton-bar category"></div><div class="skeleton-bar title-line"></div><div class="skeleton-bar title-line-short"></div><div class="skeleton-bar body-line"></div><div class="skeleton-bar body-line"></div><div class="skeleton-bar body-line-short"></div><div class="skeleton-bar cta"></div></div>`;blogGrid.innerHTML=skeletonTemplate.repeat(6);}async function fetchBlogPosts(){if(!blogGrid)return;renderSkeletons();try{const response=await fetch('https://jsonplaceholder.typicode.com/posts');if(!response.ok){throw new Error(`HTTP status:${response.status}`);}const data=await response.json();const posts=data.slice(0,6);blogGrid.innerHTML='';posts.forEach((post,index)=>{const category=categories[index % categories.length];const date=dates[index % dates.length];const formattedTitle=post.title.charAt(0).toUpperCase()+post.title.slice(1);const excerpt=post.body.charAt(0).toUpperCase()+post.body.slice(1);const card=document.createElement('article');card.className='blog-card';card.innerHTML=`<div class="blog-meta"><span class="blog-category">${category}</span><time datetime="2026-06-19" class="blog-date">${date}</time></div><h3 class="blog-card-title">${formattedTitle}</h3><p class="blog-card-excerpt">${excerpt}</p><a href="#" class="blog-read-more" aria-label="Read full article on ${formattedTitle}">Read Full Article<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a>`;blogGrid.appendChild(card);});}catch(error){console.error('Blog load error:',error);blogGrid.innerHTML=`<div class="blog-error-container"><div class="blog-error-icon" aria-hidden="true"><svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="7.86 2 16.14 2 22 7.86 22 16.14 16.14 22 7.86 22 2 16.14 2 7.86 7.86 2"></polygon><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg></div><h3 class="blog-error-title">Failed to load articles</h3><p class="blog-error-desc">There was an error retrieving the latest blog posts. Please check your internet connection and try again.</p><button id="blog-retry-btn" class="btn btn-primary blog-retry-btn">Retry Loading</button></div>`;const retryBtn=document.getElementById('blog-retry-btn');if(retryBtn){retryBtn.addEventListener('click',fetchBlogPosts);}}}fetchBlogPosts();});